import mmh3 # MurmurHash3 for fast non-cryptographic hashing

class CountMinSketch:
    def __init__(self, width, depth):
        self.width = width
        self.depth = depth
        # Initialize 2D array of zeroes
        self.table = [[0] * width for _ in range(depth)]

    def add(self, item):
        for i in range(self.depth):
            # Use the hash seed 'i' to simulate distinct independent hash functions
            col = mmh3.hash(str(item), i) % self.width
            self.table[i][col] += 1

    def estimate(self, item):
        min_count = float('inf')
        for i in range(self.depth):
            col = mmh3.hash(str(item), i) % self.width
            min_count = min(min_count, self.table[i][col])
        return min_count

public class TopKTracker {
    private final int k;
    // PriorityQueue defaults to Min-Heap in Java
    private final PriorityQueue<Item> minHeap = new PriorityQueue<>(Comparator.comparingInt(Item::getCount));

    public synchronized void updateTopK(String id, int estimatedCount) {
        // Check if item already in heap and update (complex in standard PriorityQueue, but conceptually required)
        if (minHeap.size() < k) {
            minHeap.offer(new Item(id, estimatedCount));
        } else if (estimatedCount > minHeap.peek().getCount()) {
            minHeap.poll(); // Remove smallest of the winners
            minHeap.offer(new Item(id, estimatedCount));
        }
    }
}
